buildFunc(aDoSize) {
  if (!this.vis) {
    this.vis = new DateFacetVis(this, this.canvasNode);
    this.vis.build();
  } else {
    while (this.canvasNode.hasChildNodes()) {
      this.canvasNode.lastChild.remove();
    }
    if (aDoSize) {
      this.vis.build();
    } else {
      this.vis.rebuild();
    }
  }
}
